actions.script:
// ZE-DF-001 (IV-110): opened as one merged column in Excel. Fix: quote every field, CRLF line
// endings, and a leading "sep=," directive so Excel splits on comma regardless of the user's
// regional list-separator. Also stream via getWriter + <default-response type="none"/> below
// (was url="." which re-rendered the screen after the response was committed -> a "500 Committed"
// error string got appended to the downloaded file).
def esc = { v -> '"' + (v == null ? '' : v.toString()).replace('"', '""') + '"' }
def sb = new StringBuilder()
sb.append("sep=,\r\n")
sb.append("Product ID,Period Start,Period End,Method,Forecast Qty,Actual Qty,Accuracy %\r\n")
for (def f : exportList) {
    sb.append([esc(f.productId), esc(f.periodStart), esc(f.periodEnd), esc(f.forecastMethodEnumId),
               esc(f.forecastQuantity ?: 0), esc(f.actualQuantity ?: '-'), esc(f.accuracyPercent ?: '-')].join(',')).append("\r\n")
}
ec.web.response.setContentType("text/csv; charset=UTF-8")
ec.web.response.setHeader("Content-Disposition", "attachment; filename=\"demand_forecast.csv\"")
def w = ec.web.response.getWriter(); w.write(sb.toString()); w.flush()

else.script:
def outList = []
for (p in prodList) {
    def lbl = (p.pseudoId ? (p.pseudoId + " - ") : "") + (p.productName ?: p.productId)
    outList.add([value: p.productId, label: lbl])
}
ec.web.sendJsonResponse(outList)

actions.script:
            context.hasAcc = (pastWithAccuracy != null && pastWithAccuracy.size() > 0)
            if (hasAcc) {
                def total = 0.0
                for (def f : pastWithAccuracy) total += (f.accuracyPercent ?: 0)
                avgAccuracy = (total / pastWithAccuracy.size()).setScale(0, java.math.RoundingMode.HALF_UP)
            }
            def fpset = new HashSet(); for (def f : allForecastPids) fpset.add(f.productId)
            context.forecastProductCount = fpset.size()

            // ZE-INV demand-forecast §8.1: Forecast health card — real derived values (latest compute time +
            // furthest horizon from the loaded forecasts; model is "Active" when any product is being forecast).
            def _fcLu = null; def _fcPe = null
            for (def f : forecastList) {
                if (f.lastUpdatedStamp != null && (_fcLu == null || f.lastUpdatedStamp.time > _fcLu.time)) _fcLu = f.lastUpdatedStamp
                if (f.periodEnd != null && (_fcPe == null || f.periodEnd.time > _fcPe.time)) _fcPe = f.periodEnd
            }
            context.fcUpdatedDisp = _fcLu ? ec.l10n.format(_fcLu, 'dd MMM yyyy, HH:mm') : '—'
            context.fcHorizonDisp = _fcPe ? ('through ' + ec.l10n.format(_fcPe, 'dd MMM yyyy')) : '—'
            context.fcModelActive = (forecastProductCount > 0)

            // ZE-INV demand-forecast §7 + §8.2: top-5 products by forecast demand + demand-tier distribution,
            // from the FRESHEST forecast per product (real data). Tiers = tertiles of the actual quantity
            // distribution (data-driven, not invented thresholds); No-demand = zero forecast.
            def _dfAll = ec.entity.find("zenith.erp.inventory.DemandForecast").condition("productId", "in", myProductIds).selectField("productId").selectField("forecastQuantity").selectField("periodStart").list()
            def _dfByProd = [:]
            for (def f : _dfAll) {
                def ex = _dfByProd[f.productId]
                if (ex == null || (f.periodStart != null && (ex.periodStart == null || f.periodStart > ex.periodStart))) _dfByProd[f.productId] = f
            }
            def _dfQs = _dfByProd.values().collect { (it.forecastQuantity ?: 0G) as BigDecimal }
            def _dfPos = _dfQs.findAll { it > 0G }.sort()
            distNone = _dfQs.count { it <= 0G }
            int _dfHi = 0, _dfMd = 0, _dfLo = 0
            if (_dfPos) {
                def _t1 = _dfPos[(int)(_dfPos.size() / 3)]; def _t2 = _dfPos[(int)(_dfPos.size() * 2 / 3)]
                for (def q : _dfPos) { if (q >= _t2) _dfHi++ else if (q >= _t1) _dfMd++ else _dfLo++ }
            }
            distHi = _dfHi; distMd = _dfMd; distLo = _dfLo; distTotal = _dfQs.size()
            distPctHi = distTotal > 0 ? (int)(distHi * 100 / distTotal) : 0
            distPctMd = distTotal > 0 ? (int)(distMd * 100 / distTotal) : 0
            distPctLo = distTotal > 0 ? (int)(distLo * 100 / distTotal) : 0
            distPctNone = distTotal > 0 ? (100 - distPctHi - distPctMd - distPctLo) : 0
            def _dfTop = new ArrayList(_dfByProd.values()).sort { a, b -> ((b.forecastQuantity ?: 0G) <=> (a.forecastQuantity ?: 0G)) }
            if (_dfTop.size() > 5) _dfTop = new ArrayList(_dfTop.subList(0, 5))
            def _dfMax = _dfTop ? ((_dfTop[0].forecastQuantity ?: 0G) as BigDecimal) : 0G
            def _dfNames = [:]
            if (_dfTop) ec.entity.find("mantle.product.Product").condition("productId", "in", _dfTop.collect { it.productId }).selectField("productId").selectField("productName").list().each { _dfNames[it.productId] = it.productName }
            def _dfBars = []
            for (def r : _dfTop) {
                def q = (r.forecastQuantity ?: 0G) as BigDecimal
                def pct = (_dfMax > 0G) ? q.multiply(100G).divide(_dfMax, 0, java.math.RoundingMode.HALF_UP).intValue() : 0
                _dfBars.add([name: (_dfNames[r.productId] ?: r.productId), qty: ec.l10n.format(q, '#,##0.##'), pct: pct])
            }
            topDemandBars = _dfBars

            // ===== demand-forecast §7: grouped "This vs Next period" comparison — REAL on-demand forecasts
            // (forecast#ProductDemand / forecast#CategoryDemand: avgDailyDemand = recent actual rate, forecastDemand
            // = model prediction). Toggles: dfMode product|group, dfSpan week|month. Bounded to top 5 (<=5 calls). =====
            def _dfMode = (ec.context.dfMode ?: 'product').toString()
            def _dfSpan = (ec.context.dfSpan ?: 'week').toString()
            int _spanDays = (_dfSpan == 'month') ? 30 : 7
            context.dfMode = _dfMode; context.dfSpan = _dfSpan
            context.dfSpanCap = (_dfSpan == 'month') ? 'Month' : 'Week'
            context.dfSpanLower = (_dfSpan == 'month') ? 'month' : 'week'
            context.dfModeNoun = (_dfMode == 'group') ? 'groups' : 'products'
            def _cmpLbls = []; def _cmpThis = []; def _cmpNext = []
            if (orgId && orgId != '_NA_' && _dfByProd) {
                if (_dfMode == 'group') {
                    def _allPidCat = [:]; def _allPids = new ArrayList(_dfByProd.keySet())
                    ec.entity.find("mantle.product.category.ProductCategoryMember").condition("productId", "in", _allPids).disableAuthz().list().each { if (!_allPidCat.containsKey(it.productId)) _allPidCat[it.productId] = it.productCategoryId }
                    def _catSum = [:]
                    for (def e : _dfByProd.entrySet()) { def cid = _allPidCat[e.key]; if (cid) _catSum[cid] = ((_catSum[cid] ?: 0G) as BigDecimal) + ((e.value.forecastQuantity ?: 0G) as BigDecimal) }
                    def _topCats = new ArrayList(_catSum.entrySet()).sort { a, b -> (b.value <=> a.value) }
                    if (_topCats.size() > 5) _topCats = new ArrayList(_topCats.subList(0, 5))
                    for (def c : _topCats) {
                        def _cf = null
                        try { _cf = ec.service.sync().name("zenith.inventory.AdvancedForecastServices.forecast#CategoryDemand").parameters([categoryId: c.key, organizationPartyId: orgId, horizonDays: _spanDays]).call() } catch (Exception _ce) {}
                        def _r = _cf?.result
                        def _tv = (((_r?.avgDailyDemand ?: 0) as BigDecimal).multiply(_spanDays as BigDecimal)).setScale(0, java.math.RoundingMode.HALF_UP)
                        def _nv = ((_r?.forecastDemand ?: 0) as BigDecimal).setScale(0, java.math.RoundingMode.HALF_UP)
                        _cmpLbls.add("'" + (_r?.categoryName ?: c.key).toString().replace("'", " ").replace("\"", " ") + "'"); _cmpThis.add(_tv); _cmpNext.add(_nv)
                    }
                } else {
                    def _cmpP = new ArrayList(_dfByProd.values()).sort { a, b -> ((b.forecastQuantity ?: 0G) <=> (a.forecastQuantity ?: 0G)) }
                    if (_cmpP.size() > 5) _cmpP = new ArrayList(_cmpP.subList(0, 5))
                    for (def r : _cmpP) {
                        def _pf = null
                        try { _pf = ec.service.sync().name("zenith.inventory.AdvancedForecastServices.forecast#ProductDemand").parameters([productId: r.productId, organizationPartyId: orgId, horizonDays: _spanDays]).call() } catch (Exception _pe) {}
                        def _r = _pf?.result
                        def _tv = (((_r?.avgDailyDemand ?: 0) as BigDecimal).multiply(_spanDays as BigDecimal)).setScale(0, java.math.RoundingMode.HALF_UP)
                        def _nv = ((_r?.forecastDemand ?: 0) as BigDecimal).setScale(0, java.math.RoundingMode.HALF_UP)
                        _cmpLbls.add("'" + (_dfNames[r.productId] ?: r.productId).toString().replace("'", " ").replace("\"", " ") + "'"); _cmpThis.add(_tv); _cmpNext.add(_nv)
                    }
                }
            }
            context.dfCmpLabels = "[" + _cmpLbls.join(",") + "]"
            context.dfCmpThis = "[" + _cmpThis.join(",") + "]"
            context.dfCmpNext = "[" + _cmpNext.join(",") + "]"
            context.dfCmpHas = (_cmpLbls.size() > 0)

            def confWord = { p -> p == null ? "Still learning" : (p >= 75 ? "Strong" : (p >= 60 ? "Good" : (p >= 45 ? "Fair" : "Still learning"))) }
            context.accWord = hasAcc ? confWord(avgAccuracy) : "Building up"
            context.accColor = !hasAcc ? "grey" : (avgAccuracy >= 60 ? "success" : (avgAccuracy >= 45 ? "warning" : "grey"))
            context.alertColor = (alertCount > 0) ? "danger" : "success"
            context.plain = "We're predicting how much of each product you'll sell, so you can restock at the right time. " +
                "We're keeping an eye on " + forecastProductCount + " products. " +
                (alertCount > 0 ? (alertCount + (alertCount == 1 ? " item needs" : " items need") + " your attention right now — see the list just below.") :
                                  "Nothing needs attention right now — everything is selling normally and stock looks healthy.") +
                (hasAcc ? (" When we check our past predictions against what really sold, we've been about " + avgAccuracy + "% accurate (" + accWord.toLowerCase() + ").") :
                          " Once a few predictions have been checked against real sales, you'll see how accurate we are here.")

int _oh = (reorderCfg?.openHour ?: 8) as int
int _ch = (reorderCfg?.closeHour ?: 22) as int
context.reorderOpenHour = _oh.toString()
context.reorderCloseHour = _ch.toString()
def _lbl = { int h -> h == 0 ? "12 AM (midnight)" : (h == 24 ? "12 AM (next day)" : (h == 12 ? "12 noon" : (h < 12 ? (h + " AM") : (h - 12) + " PM"))) }
def _open = []; for (int h = 0; h <= 23; h++) _open.add([h: h.toString(), label: _lbl(h)])
def _close = []; for (int h = 1; h <= 24; h++) _close.add([h: h.toString(), label: _lbl(h)])
context.openHourOptions = _open
context.closeHourOptions = _close
context.reorderHoursText = _lbl(_oh) + " – " + _lbl(_ch)
// IV-113 (ZE-DF-009): "Check a product" — look up ANY product (incl. a brand-new one with no sales)
// and show its forecast + sales history. forecast#ProductDemand returns a plain-English summary that
// already distinguishes has-sales vs "No sales history found ... a forecast cannot be produced yet".
context.checkDone = false; context.checkFound = false; context.checkHasForecast = false
context.checkTracked = false; context.checkSoh = 0; context.checkMaintained = false; context.checkReorderEligible = false
def _cn = ec.context.checkProductName
if (_cn != null) _cn = _cn.toString().trim()
if (_cn && orgId && orgId != '_NA_') {
    context.checkDone = true
    context.checkQuery = _cn
    def _prod = ec.entity.find("mantle.product.Product").condition("productId", _cn).condition("ownerPartyId", orgId).disableAuthz().one()
    if (_prod == null) {
        def _pl = ec.entity.find("mantle.product.Product").condition("ownerPartyId", orgId).condition("productName", "like", "%" + _cn + "%").disableAuthz().orderBy("productName").limit(1).list()
        if (_pl) _prod = _pl[0]
    }
    if (_prod != null) {
        context.checkFound = true
        context.checkPName = _prod.productName
        context.checkPseudo = _prod.pseudoId
        def _fout = ec.service.sync().name("zenith.inventory.AdvancedForecastServices.forecast#ProductDemand")
            .parameters([productId: _prod.productId, organizationPartyId: orgId, horizonDays: 14]).call()
        context.checkSummary = _fout?.summary
        def _r = _fout?.result
        context.checkResult = _r
        context.checkHasForecast = (_r != null && _r.forecastDemand != null)
        // IV-114: mirror check#ProductReorder EXACTLY so the tester can see whether this product is
        // eligible for low-stock/reorder alerts. tracked = has >=1 org-scoped Asset with hasQuantity='Y';
        // soh = sum(quantityOnHandTotal); maintainedStockout = tracked lot has AssetDetail ledger history.
        // Reorder alert fires iff tracked && (soh > 0 || maintainedStockout). Untracked -> excluded.
        double _soh = 0.0; boolean _tracked = false; List _tAssetIds = []
        ec.entity.find("mantle.product.asset.Asset").condition("productId", _prod.productId).condition("ownerPartyId", orgId)
            .selectField("assetId").selectField("quantityOnHandTotal").selectField("hasQuantity").disableAuthz().list().each {
                _soh += ((it.quantityOnHandTotal ?: 0) as double)
                if (it.hasQuantity == 'Y') { _tracked = true; _tAssetIds.add(it.assetId) }
            }
        boolean _maintained = false
        if (_tracked && _soh <= 0 && _tAssetIds) {
            _maintained = ec.entity.find("mantle.product.asset.AssetDetail").condition("assetId", "in", _tAssetIds).disableAuthz().count() > 0
        }
        context.checkTracked = _tracked
        context.checkSoh = (int) Math.round(_soh)
        context.checkMaintained = _maintained
        context.checkReorderEligible = (_tracked && (_soh > 0 || _maintained))
    }
}
// ZE-DF-008 f/u: does this org have Store operating hours? If so they OVERRIDE the setting below,
// so show a note. Stays false (note hidden) until the stores module is actually used -> no dead pointer.
context.hasStoreHours = false
if (orgId && orgId != '_NA_') {
    def _stids = ec.entity.find("zenith.erp.stores.Store").condition("organizationPartyId", orgId).disableAuthz().selectField("storeId").list()*.storeId
    if (_stids) context.hasStoreHours = ec.entity.find("zenith.erp.stores.StoreOperatingHours").condition("storeId", "in", _stids).disableAuthz().count() > 0
}
// demand-forecast §6: surface-correct URL for the "View all products" stat-card link.
def _dfB = (ec.web?.request?.requestURI ?: '').replaceAll('/+$','')
context.dfProdUrl = _dfB.contains('/') ? (_dfB.substring(0, _dfB.lastIndexOf('/')) + '/FindProduct') : '/apps/zenith/Inventory/FindProduct'
